import json,collections
meta={}
for l in open('/workspace/case/dataset/train_curve.meta.jsonl'):
    r=json.loads(l); meta[r.get('id') or r.get('example_id')]=r
def load(n):
    d=json.load(open(f'{n}-curve.json'))
    return {e['example_id']:e for e in d['examples']}
R={n:load(n) for n in ['r6-01','r4-01','r7-01','r5-02','r2-04','r1-03']}
ids=list(R['r6-01'])
def top1(n,i): 
    a=json.loads(R[n][i]['answer']); return a[0] if a else None
def gold(i): return json.loads(R['r6-01'][i]['reference'])
st=lambda i: meta[i].get('style')
print(list(meta[ids[0]].keys()))
for pair in [('r6-01','r4-01'),('r6-01','r7-01')]:
    a,b=pair
    cnt=collections.Counter()
    for i in ids:
        sa,sb=R[a][i]['score'],R[b][i]['score']
        cnt[(st(i),'a>b' if sa>sb else 'a<b' if sa<sb else '=')]+=1
    print(pair)
    for s in sorted({st(i) for i in ids}):
        print(' ',s,cnt[(s,'a>b')],cnt[(s,'a<b')],cnt[(s,'=')])
# oracle among top1 of r6 or r4
for s in sorted({st(i) for i in ids}):
    ii=[i for i in ids if st(i)==s]
    f=lambda n: sum(R[n][i]['statistics']['acc1'] for i in ii)/len(ii)
    orc=sum(max(R['r6-01'][i]['statistics']['acc1'],R['r4-01'][i]['statistics']['acc1']) for i in ii)/len(ii)
    print(s,len(ii),'r6',round(f('r6-01'),3),'r4',round(f('r4-01'),3),'r7',round(f('r7-01'),3),'oracle r6|r4',round(orc,3),
      'r6 gold in top3', sum(1 for i in ii if json.loads(R['r6-01'][i]['reference'])['primary'] in json.loads(R['r6-01'][i]['answer']))/len(ii))
E

