input.content:
import json, collections
RUNS = '/workspace/case/campaigns/c1/runs/'
meta = {}
for l in open('/workspace/case/dataset/train_curve.meta.jsonl'):
    r = json.loads(l)
    meta[r.get('id') or r.get('example_id')] = r


def load(n):
    d = json.load(open(RUNS + f'{n}-curve.json'))
    return {e['example_id']: e for e in d['examples']}


R = {n: load(n) for n in ['r6-01', 'r4-01', 'r7-01', 'r5-02', 'r2-04', 'r1-03']}
ids = list(R['r6-01'])
print(list(meta[ids[0]].keys()))
st = lambda i: meta[i].get('style')
for a, b in [('r6-01', 'r4-01'), ('r6-01', 'r7-01')]:
    cnt = collections.Counter()
    for i in ids:
        sa, sb = R[a][i]['score'], R[b][i]['score']
        cnt[(st(i), '>' if sa > sb else '<' if sa < sb else '=')] += 1
    print(a, 'vs', b, '(better/worse/equal)')
    for s in sorted({st(i) for i in ids}):
        print('  ', s, cnt[(s, '>')], cnt[(s, '<')], cnt[(s, '=')])
for s in sorted({st(i) for i in ids}):
    ii = [i for i in ids if st(i) == s]
    f = lambda n: sum(R[n][i]['statistics']['acc1'] for i in ii) / len(ii)
    orc = sum(max(R['r6-01'][i]['statistics']['acc1'], R['r4-01'][i]['statistics']['acc1']) for i in ii) / len(ii)
    both_miss = sum(1 for i in ii if R['r6-01'][i]['statistics']['acc1'] == 0 and R['r4-01'][i]['statistics']['acc1'] == 0)
    g3 = sum(1 for i in ii if json.loads(R['r6-01'][i]['reference'])['primary'] in json.loads(R['r6-01'][i]['answer'])) / len(ii)
    print(s, len(ii), 'r6', round(f('r6-01'), 3), 'r4', round(f('r4-01'), 3), 'r7', round(f('r7-01'), 3), 'r1-03', round(f('r1-03'), 3),
          'oracle r6|r4', round(orc, 3), 'both miss', both_miss, 'r6 gold@3', round(g3, 3))

